<script setup>
import {ref,computed,watch,onActivated,onDeactivated,onUnmounted,markRaw,nextTick} from 'vue';
import SectionTabs from '../components/SectionTabs.vue';
import BaseModal from '../components/BaseModal.vue';
import AccountSelect from '../components/AccountSelect.vue';
import Icon from '../components/Icon.vue';
import {state,company,api,scope,can,changed,captureContext,contextMatches} from '../lib/workspace';
import {money,date,normalized,uid} from '../lib/format';
import {useSuggestedMonth} from '../lib/context-preferences.js';
const section=ref('notes'),sectionTabs=ref(null);
const sections=[{id:'notes',label:'Notas e seleção'},{id:'accounting',label:'Contabilizar'},{id:'settings',label:'Parâmetros e ajuda'}];
const accessTitle=computed(()=>state.module==='accounting'?'Integração Fiscal':'Integração Contábil');
function selectSection(value){section.value=value;nextTick(()=>sectionTabs.value?.focusTab(value));}
const direction=ref('outgoing'),preview=ref(null),previewLoading=ref(false);
const config=ref(null),mode=ref('individual'),documents=ref([]),models=ref([]),accounts=ref([]),centers=ref([]);
const debitAccount=ref(''),creditAccount=ref(''),costCenter=ref('');
const loading=ref(false),busy=ref(false),error=ref(''),result=ref(null),intent=ref(null);
const query=ref(''),month=ref(state.period.slice(5)),status=ref('all'),page=ref(1),pageSize=ref(50);
const selectedIds=ref([]),modelIds=ref({}),commonModel=ref(''),reason=ref('');
const trace=ref(null),traceLoading=ref(false),traceError=ref('');
let alive=true,active=true,sequence=0,traceSequence=0,reader=null,scheduled=null,previewReader=null,previewSequence=0;
useSuggestedMonth(state,month);
const modeDirty=computed(()=>direction.value==='outgoing'&&!!config.value&&mode.value!==config.value.mode);
const endpoint=computed(()=>direction.value==='incoming'?'/fiscal-purchases-accounting':'/fiscal-sales-accounting');
const directionLabel=computed(()=>direction.value==='incoming'?'entradas':'saídas');
const permitted=computed(()=>can('fiscal.documents')&&can('accounting.accounts'));
const canGenerate=computed(()=>permitted.value&&can('accounting.journals','create'));
const locked=computed(()=>busy.value||!!intent.value||state.contextBusy);
const eligible=d=>d.direction===direction.value&&d.status==='booked'&&!d.journal_id&&!d.book_cancellation&&d.document_state!=='cancelled'&&d.total_cents>0;
const selection=computed(()=>documents.value.filter(d=>selectedIds.value.includes(d.id)));
const filtered=computed(()=>documents.value.filter(d=>(!month.value||d.period.slice(5)===month.value)&&
 (status.value==='all'||(status.value==='eligible'?eligible(d):status.value==='accounted'?!!d.journal_id:!eligible(d)&&!d.journal_id))&&
 normalized(`${d.number} ${d.partner_name} ${d.cfop} ${d.key}`).includes(normalized(query.value))));
const pageCount=computed(()=>Math.max(1,Math.ceil(filtered.value.length/pageSize.value)));
const visible=computed(()=>filtered.value.slice((page.value-1)*pageSize.value,page.value*pageSize.value));
const selectedTotal=computed(()=>selection.value.reduce((n,d)=>n+BigInt(d.total_cents),0n));
const wholeFormatter=new Intl.NumberFormat('pt-BR');
const selectedAmount=computed(()=>`R$ ${wholeFormatter.format(selectedTotal.value/100n)},${String(selectedTotal.value%100n).padStart(2,'0')}`);
const directSelection=computed(()=>selection.value.filter(d=>!modelIds.value[d.id]));
const usableAccounts=computed(()=>accounts.value.filter(a=>a.active&&a.analytical));
const accountFor=id=>usableAccounts.value.find(a=>a.id===Number(id))||(Number(id)<0?usableAccounts.value.find(a=>a.shared_entry_id===-Number(id)):null);
const directIssue=computed(()=>!directSelection.value.length?'':
 !accountFor(debitAccount.value)||!accountFor(creditAccount.value)?'Informe as contas a debitar e a creditar para as notas sem modelo.':
 accountFor(debitAccount.value).id===accountFor(creditAccount.value).id?'Selecione contas diferentes para débito e crédito.':
 (accountFor(debitAccount.value).requires_cost_center||accountFor(creditAccount.value).requires_cost_center)&&!costCenter.value?'Informe o centro de custo exigido pelas contas selecionadas.':
 costCenter.value&&!centers.value.some(c=>c.active&&c.id===Number(costCenter.value))?'Selecione um centro de custo ativo desta empresa.':'');
const availableModels=computed(()=>models.value.filter(m=>m.active&&m.data.status==='validated'&&[direction.value,'both'].includes(m.data.direction)));
const modelFits=(m,d)=>m&&m.data.valid_from<=d.posting_date&&(!m.data.valid_to||m.data.valid_to>=d.posting_date);
const modelFor=id=>availableModels.value.find(m=>m.id===Number(id));
const closure=computed(()=>selection.value.find(d=>state.yearLocks?.fiscal?.[d.period]?.closed||state.yearLocks?.accounting?.[d.period]?.closed)?.period||'');
const selectionIssue=computed(()=>!selection.value.length?'Selecione notas escrituradas sem lançamento.':
 selectedIds.value.length!==selection.value.length?'Atualize a consulta e selecione novamente.':
 selection.value.length>1000?'A API aceita até 1000 notas por solicitação. Refine a seleção.':
 selection.value.some(d=>!eligible(d))?'Há notas que já não estão aptas. Atualize a consulta.':
 closure.value?`A competência ${closure.value} está fechada no fiscal ou contábil. Reabra para contabilizar.`:
 selection.value.some(d=>modelIds.value[d.id]&&!modelFits(modelFor(modelIds.value[d.id]),d))?'O modelo opcional deve estar revisado e vigente para a nota selecionada.':directIssue.value);
const canSubmit=computed(()=>active&&alive&&canGenerate.value&&!locked.value&&!loading.value&&!!config.value&&!modeDirty.value&&!selectionIssue.value&&!state.editor);
function clearSelection(){debitAccount.value='';creditAccount.value='';costCenter.value='';selectedIds.value=[];modelIds.value={};commonModel.value='';reason.value='';}
function contextKey(){return `${state.companyId}:${state.module}:${state.period}:${direction.value}`;}
function valid(n,key){return alive&&active&&n===sequence&&key===contextKey()&&!state.contextBusy;}
function release(owner){if(state.editor===owner)state.editor=null;}
function clearPreview(){previewSequence++;previewReader?.abort();preview.value=null;previewLoading.value=false;}
function resetContext(){section.value='notes';clearPreview();sequence++;traceSequence++;reader?.abort();trace.value=null;traceLoading.value=false;traceError.value='';config.value=null;documents.value=[];models.value=[];accounts.value=[];centers.value=[];mode.value='individual';result.value=null;intent.value=null;error.value='';loading.value=false;clearSelection();}
async function load({discardIntent=false}={}){
 if(!alive||!active||!state.companyId||state.contextBusy||busy.value)return;
 clearPreview();const n=++sequence,key=contextKey(),cid=state.companyId,year=state.period.slice(0,4),draft=mode.value,dirty=modeDirty.value;
 reader?.abort();reader=new AbortController();loading.value=true;error.value='';
 try{
  if(!permitted.value){config.value=null;documents.value=[];models.value=[];accounts.value=[];centers.value=[];clearSelection();return;}
  const [cfg,docs,mods,acc,cc]=await Promise.all([api(scope('/fiscal-sales-accounting/settings',cid),{signal:reader.signal}),api(scope(`/documents?year=${year}`,cid),{signal:reader.signal}),can('accounting.histories')?api(scope('/masters/accounting_model',cid),{signal:reader.signal}):Promise.resolve([]),api(scope('/accounts',cid),{signal:reader.signal}),can('accounting.cost_centers')?api(scope('/cost-centers',cid),{signal:reader.signal}):Promise.resolve([])]);
  if(!valid(n,key))return;
  config.value=cfg;mode.value=dirty&&!discardIntent?draft:cfg.mode;documents.value=docs.filter(d=>d.direction===direction.value);models.value=mods;accounts.value=acc;centers.value=cc;
  if(discardIntent){intent.value=null;result.value=null;clearSelection();}
 }catch(e){if(valid(n,key)&&e.name!=='AbortError')error.value=e.message;}
 finally{if(alive&&n===sequence)loading.value=false;}
}
function scheduleLoad(){clearTimeout(scheduled);scheduled=setTimeout(()=>load(),0);}
watch(direction,()=>{resetContext();scheduleLoad();},{flush:'sync'});
watch([selectedIds,modelIds,debitAccount,creditAccount,costCenter,reason,mode,()=>config.value?.version],clearPreview,{deep:true,flush:'sync'});
watch([()=>state.companyId,()=>state.module,()=>state.period],()=>{resetContext();scheduleLoad();},{flush:'sync'});
watch([()=>JSON.stringify(state.session?.permissions),()=>state.session?.user?.role],()=>{resetContext();scheduleLoad();},{flush:'sync'});
watch([()=>state.contextBusy,()=>state.refresh],()=>{
 if(state.contextBusy){clearPreview();sequence++;reader?.abort();traceSequence++;trace.value=null;return;}scheduleLoad();});
watch([query,month,status,pageSize],()=>{page.value=1;if(!intent.value)clearSelection();},{flush:'sync'});
watch(pageCount,n=>page.value=Math.min(page.value,n));
onActivated(()=>{active=true;scheduleLoad();});
onDeactivated(()=>{clearPreview();active=false;sequence++;traceSequence++;reader?.abort();clearTimeout(scheduled);trace.value=null;traceLoading.value=false;});
onUnmounted(()=>{clearPreview();alive=false;active=false;sequence++;traceSequence++;reader?.abort();clearTimeout(scheduled);});
scheduleLoad();
function toggle(d,checked){if(locked.value||loading.value||!canGenerate.value||!eligible(d))return;selectedIds.value=checked?[...new Set([...selectedIds.value,d.id])]:selectedIds.value.filter(id=>id!==d.id);if(checked&&!modelIds.value[d.id])modelIds.value[d.id]='';}
function selectFiltered(){if(locked.value||loading.value||!canGenerate.value)return;const ids=filtered.value.filter(eligible).map(d=>d.id);if(ids.length>1000){error.value='A consulta tem mais de 1000 notas aptas. Refine os filtros ou selecione manualmente.';return;}selectedIds.value=ids;for(const id of ids)if(!modelIds.value[id])modelIds.value[id]='';error.value='';}
function applyModel(){if(locked.value||!selection.value.length)return;const model=modelFor(commonModel.value);if(!model||selection.value.some(d=>!modelFits(model,d))){error.value='O modelo deve estar revisado e vigente em todas as notas selecionadas.';return;}modelIds.value={...modelIds.value,...Object.fromEntries(selection.value.map(d=>[d.id,model.id]))};error.value='';}
function useDirectAccounts(){if(locked.value)return;modelIds.value={...modelIds.value,...Object.fromEntries(selection.value.map(d=>[d.id,'']))};commonModel.value='';}
function accountingEntries(){return selection.value.map(d=>({document_id:d.id,version:d.version,...(modelIds.value[d.id]?{model_id:Number(modelIds.value[d.id])}:{debit_account_id:Number(debitAccount.value),credit_account_id:Number(creditAccount.value),cost_center_id:costCenter.value?Number(costCenter.value):null})}));}
async function saveMode(){
 if(direction.value!=='outgoing'||!config.value||!modeDirty.value||!can('accounting.accounts','edit')||locked.value||loading.value||state.editor)return;
 const n=sequence,key=contextKey(),ctx=captureContext(),cid=state.companyId,value=mode.value,owner=markRaw({name:'Configuração da integração contábil',companyId:cid});
 busy.value=true;error.value='';state.editor=owner;
 try{const saved=await api(scope('/fiscal-sales-accounting/settings',cid),{method:'PUT',context:ctx,body:{version:config.value.version,mode:value}});if(valid(n,key)){config.value=saved;mode.value=saved.mode;result.value=null;}}
 catch(e){if(valid(n,key))error.value=`${e.message} Recarregue os parâmetros para conferir o modo salvo.`;}
 finally{release(owner);if(alive){busy.value=false;if(active&&(key!==contextKey()||!config.value))scheduleLoad();}}
}
async function generate(replay=false){
 if(!alive||!active)return;
 if(replay){if(!intent.value||busy.value||state.contextBusy||!contextMatches(intent.value.context)||intent.value.key!==contextKey()||!active||!canGenerate.value||state.editor)return;}
 else{if(!canSubmit.value)return;intent.value={key:contextKey(),context:captureContext(),endpoint:endpoint.value,body:{settings_version:config.value.version,idempotency_key:uid(),reason:reason.value.trim(),entries:accountingEntries()}};}
 const pending=intent.value,n=sequence,key=contextKey(),cid=pending.context.companyId,owner=markRaw({name:'Integração contábil fiscal',companyId:cid});
 clearPreview();busy.value=true;state.editor=owner;error.value='';result.value=null;
 try{const response=await api(scope(`${pending.endpoint}/generate`,cid),{method:'POST',context:pending.context,body:pending.body});
  if(!valid(n,key))return;result.value=response;intent.value=null;clearSelection();changed();
 }catch(e){if(valid(n,key)){
  if(e.status&&e.status<500){intent.value=null;error.value=e.message;}
  else error.value='O resultado não foi confirmado. Confira os vínculos atualizando a consulta ou repita a mesma solicitação; a repetição usa a mesma chave e não duplica lançamentos.';
 }}finally{release(owner);if(alive){busy.value=false;if(active&&(key!==contextKey()||!config.value))scheduleLoad();}}
}
async function showPreview(){
 if(!canSubmit.value||!can('accounting.journals'))return;
 clearPreview();const n=previewSequence,seq=sequence,key=contextKey(),cid=state.companyId;
 previewReader=new AbortController();previewLoading.value=true;error.value='';
 const body={settings_version:config.value.version,reason:reason.value.trim(),entries:accountingEntries()};
 try{const response=await api(scope(`${endpoint.value}/preview`,cid),{method:'POST',context:captureContext(),signal:previewReader.signal,body});
  if(n===previewSequence&&valid(seq,key))preview.value=response;
 }catch(e){if(n===previewSequence&&valid(seq,key)&&e.name!=='AbortError')error.value=e.message;}
 finally{if(alive&&n===previewSequence)previewLoading.value=false;}
}
function closeTrace(){traceSequence++;trace.value=null;traceLoading.value=false;traceError.value='';}
async function showTrace(kind,id){
 if(!active||state.contextBusy||!can('accounting.journals')||!can('fiscal.documents'))return;
 const n=++traceSequence,key=contextKey(),cid=state.companyId;trace.value={kind,data:null};traceLoading.value=true;traceError.value='';
 try{const path=kind==='journal'?`/fiscal-sales-accounting/journals/${id}/sources`:`/documents/${id}/trace`;const response=await api(scope(path,cid));if(alive&&active&&n===traceSequence&&key===contextKey()&&!state.contextBusy)trace.value={kind,data:response};}
 catch(e){if(alive&&active&&n===traceSequence&&key===contextKey())traceError.value=e.message;}
 finally{if(alive&&n===traceSequence)traceLoading.value=false;}
}
const traceSources=computed(()=>trace.value?.data?.sources||trace.value?.data?.accounting_sources||[]);
const traceJournals=computed(()=>trace.value?.data?.journal?[trace.value.data.journal]:trace.value?.data?.journals||[]);
const eligibilityLabel=d=>d.journal_id?'Já contabilizada':d.document_state==='cancelled'||d.book_cancellation?'Cancelada':d.status!=='booked'?'Ainda não escriturada':!d.total_cents?'Sem valor contábil':'Apta à contabilização';
const classLabel=c=>[c.cfop&&`CFOP ${c.cfop}`,c.cst_icms&&`CST ${c.cst_icms}`,c.csosn&&`CSOSN ${c.csosn}`,c.ncm&&`NCM ${c.ncm}`,c.rate!=null&&`Alíquota ${c.rate}%`,c.cclass_trib&&`ClassTrib ${c.cclass_trib}`,...Object.entries(c.declared_tax_classifications||{}).map(([k,v])=>`${k}: ${v}`)].filter(Boolean).join(' · ')||'Sem classificação adicional informada';
</script>
<template><div class="view sales-accounting-view">
<header class="view-heading"><div><div class="eyebrow">FISCAL ↔ CONTÁBIL</div><h1>{{accessTitle}}</h1><p>{{company?.code}} · {{company?.trade_name||company?.name}} · exercício {{state.period.slice(0,4)}}</p></div><button class="button outline" aria-label="Atualizar consulta e parâmetros" :disabled="busy||loading||state.contextBusy" @click="load({discardIntent:true})">Atualizar</button></header>
<p v-if="!permitted" class="message warning" role="status">Para consultar esta integração são necessárias permissões de leitura de documentos fiscais e contas contábeis. Modelos são opcionais.</p>
<section v-if="permitted" class="panel sales-context" aria-label="Contexto da integração"><label>Sentido da integração<select v-model="direction" :disabled="locked"><option value="outgoing">Saídas</option><option value="incoming">Entradas · individual por nota</option></select></label><label>Competência da escrituração<select v-model="month" :disabled="locked"><option value="">Todo o exercício</option><option v-for="m in 12" :key="m" :value="String(m).padStart(2,'0')">{{String(m).padStart(2,'0')}}/{{state.period.slice(0,4)}}</option></select></label><div class="sales-mode"><strong>{{direction==='incoming'?'Entradas individuais':config?`Saídas ${config.mode==='daily'?'diárias':'individuais'}`:'Carregando modo…'}}</strong><button type="button" class="text-button" @click="selectSection('settings')">Ver parâmetros</button><small v-if="modeDirty">Alteração de modo não salva</small></div></section>
<p v-if="loading" class="report-note" role="status">Carregando notas e parâmetros desta empresa…</p><p v-if="error" class="message error" role="alert">{{error}}</p>
<section v-if="permitted" class="sales-selection-summary" aria-label="Resumo da seleção"><div aria-live="polite"><strong>{{selection.length}} selecionadas · {{selectedAmount}}</strong><small>{{filtered.length}} {{directionLabel}} na consulta{{month?` · ${month}/${state.period.slice(0,4)}`:' · todo o exercício'}}</small><small v-if="previewLoading" role="status">Consultando prévia…</small></div><div class="actions"><button v-if="section!=='notes'" class="button outline" @click="selectSection('notes')">Rever notas</button><button v-if="section!=='accounting'" class="button primary" :disabled="loading||(!selectedIds.length&&!result&&!intent)" @click="selectSection('accounting')">{{result?'Ver resultado':intent?'Rever solicitação':preview||previewLoading?'Ver prévia':`Contabilizar seleção (${selection.length})`}}</button></div></section>
<SectionTabs v-if="permitted" ref="sectionTabs" id="fiscal-accounting" label="Seções da integração contábil" v-model="section" :tabs="sections"/>
<section v-if="permitted" v-show="section==='notes'" id="fiscal-accounting-panel-notes" role="tabpanel" aria-labelledby="fiscal-accounting-tab-notes" class="panel sales-notes"><div class="table-toolbar"><label>Pesquisar notas<input v-model="query" :disabled="locked" placeholder="Número, participante, CFOP ou chave"/></label><label>Situação contábil<select v-model="status" :disabled="locked"><option value="all">Todas as notas</option><option value="eligible">Aptas à contabilização</option><option value="accounted">Já contabilizadas</option><option value="other">Demais situações</option></select></label><label>Notas por página<select v-model.number="pageSize" :disabled="locked"><option :value="50">50</option><option :value="100">100</option><option :value="250">250</option></select></label></div>
<div class="sales-selection"><div class="actions"><button class="button small" :disabled="locked||loading||!canGenerate" @click="selectFiltered">Selecionar aptas da consulta</button><button class="button small" :disabled="locked||!selectedIds.length" @click="clearSelection">Limpar seleção contábil</button></div><small>Selecionar a consulta inclui outras páginas. Mudar filtros limpa a seleção; mudar apenas a página a preserva.</small></div>
<div class="table-scroll"><table><thead><tr><th>Selecionar</th><th>Nota / participante</th><th>Escrituração</th><th>CFOP</th><th class="right">Total</th><th>Situação</th><th>Forma de contabilização</th><th>Origem</th></tr></thead><tbody><tr v-for="d in visible" :key="d.id"><td><input type="checkbox" :aria-label="`Contabilizar nota ${d.number}`" :checked="selectedIds.includes(d.id)" :disabled="locked||loading||!canGenerate||!eligible(d)" @change="toggle(d,$event.target.checked)"/></td><td><strong>{{d.number}}</strong><small class="cell-secondary">{{d.partner_name}} · modelo {{d.model}} · série {{d.series}}</small></td><td>{{date(d.posting_date)}}<small class="cell-secondary">Emissão {{date(d.issue_date)}}</small></td><td>{{d.cfop||'Não informado'}}</td><td class="right">{{money(d.total_cents)}}</td><td>{{eligibilityLabel(d)}}</td><td><select v-if="selectedIds.includes(d.id)&&can('accounting.histories')" v-model.number="modelIds[d.id]" :aria-label="`Modelo contábil da nota ${d.number}`" :disabled="locked"><option value="">Contas informadas nesta seleção</option><option v-for="m in availableModels.filter(m=>modelFits(m,d))" :key="m.id" :value="m.id">{{m.code}} · {{m.name}}</option></select><span v-else>{{selectedIds.includes(d.id)?'Contas informadas nesta seleção':'—'}}</span></td><td><button type="button" class="button small" :disabled="state.contextBusy||!can('accounting.journals')" @click="showTrace('document',d.id)">Origem da nota {{d.number}}</button></td></tr></tbody></table><p v-if="!loading&&!filtered.length" class="report-note">Nenhuma nota nos filtros selecionados.</p></div>
<footer class="table-footer"><span>Página {{page}} de {{pageCount}}</span><div class="actions"><button class="button small" :disabled="page<=1||loading" @click="page--">Página anterior</button><button class="button small" :disabled="page>=pageCount||loading" @click="page++">Página seguinte</button></div></footer>
</section>
<section v-if="permitted" v-show="section==='accounting'" id="fiscal-accounting-panel-accounting" role="tabpanel" aria-labelledby="fiscal-accounting-tab-accounting" class="sales-accounting-panel"><div class="panel"><div class="sales-generation"><h2>Contabilizar seleção</h2><p class="report-note">Informe as contas e confira a seleção. Modelos salvos são opcionais.</p><div v-if="!selection.length||directSelection.length" class="form-grid" aria-label="Contas diretas da seleção"><label>Conta a debitar<AccountSelect v-model="debitAccount" :accounts="usableAccounts" aria-label="Conta a debitar na integração" :disabled="locked||loading"/></label><label>Conta a creditar<AccountSelect v-model="creditAccount" :accounts="usableAccounts" aria-label="Conta a creditar na integração" :disabled="locked||loading"/></label><label>Centro de custo (quando necessário)<select v-model.number="costCenter" :disabled="locked||loading||!can('accounting.cost_centers')"><option value="">Sem centro informado</option><option v-for="c in centers.filter(c=>c.active)" :key="c.id" :value="c.id">{{c.code}} · {{c.name}}</option></select></label></div><details v-if="can('accounting.histories')" class="sales-optional-model"><summary>Usar modelo salvo (opcional)</summary><div class="form-grid"><label>Modelo comum para as selecionadas<select v-model.number="commonModel" :disabled="locked||!selection.length"><option value="">Selecione se quiser usar um modelo</option><option v-for="m in availableModels" :key="m.id" :value="m.id">{{m.code}} · {{m.name}}</option></select></label><button type="button" class="button outline" :disabled="locked||!selection.length||!commonModel" @click="applyModel">Aplicar modelo às selecionadas</button><button type="button" class="button outline" :disabled="locked||!selection.length" @click="useDirectAccounts">Usar contas informadas para todas</button></div></details><label>Histórico do lançamento (opcional)<input v-model="reason" :disabled="locked" maxlength="1000" placeholder="Em branco: descrição padrão da integração fiscal"/></label>
<p v-if="!canGenerate" class="message info">Seu usuário pode consultar, mas não possui as permissões necessárias para gerar lançamentos.</p><p v-if="modeDirty" class="message info">Salve o modo da empresa antes de gerar.</p><p v-if="selectionIssue&&selectedIds.length" class="message info">{{selectionIssue}}</p><p v-if="intent&&!busy" class="message warning">Há uma solicitação sem resultado confirmado. Repetir envia exatamente a mesma seleção e chave. Atualizar consulta e parâmetros permite conferir os vínculos antes de selecionar novamente.</p><div class="actions sales-post-actions"><button v-if="previewLoading" type="button" class="button outline" @click="clearPreview">Cancelar consulta da prévia</button><button type="button" class="button outline" :disabled="!canSubmit||previewLoading||!can('accounting.journals')" @click="showPreview">{{previewLoading?'Consultando prévia…':'Consultar prévia contábil'}}</button><button v-if="intent&&!busy" type="button" class="button primary" :disabled="!canGenerate||state.contextBusy" @click="generate(true)">Repetir a mesma solicitação</button><button v-else type="button" class="button primary" :disabled="!canSubmit" @click="generate(false)"><Icon v-if="busy" name="loading"/>{{busy?'Processando…':'Gerar lançamentos da seleção'}}</button></div></div></div><section v-if="preview" class="panel sales-result" aria-label="Prévia contábil"><h2>Prévia contábil · somente leitura</h2><p>{{preview.created_count}} lançamento(s) previsto(s) · {{preview.accounted_count}} nota(s) · {{preview.skipped.length}} ignorada(s). Nenhum lançamento foi gerado. A execução revalida os dados atuais.</p><article v-for="(j,i) in preview.journals" :key="i"><h3>{{date(j.date)}} · {{money(j.total_cents)}} · {{j.document_ids.length}} nota(s)</h3><p>Origens: {{preview.sources.filter(s=>j.document_ids.includes(s.document_id)).map(s=>s.document_number).join(', ')}}</p><p v-for="(l,index) in j.lines" :key="index">{{l.account_code}} · {{l.account_name}} · Débito {{money(l.debit_cents)}} · Crédito {{money(l.credit_cents)}}<span v-if="l.participant_id"> · Terceiro #{{l.participant_id}}</span><span v-if="l.cost_center_id"> · Centro #{{l.cost_center_id}}</span></p></article><button class="button outline" @click="clearPreview">Fechar prévia</button></section>
<section v-if="result" class="panel sales-result" aria-label="Resultado da contabilização"><h2>{{result.duplicate?'Solicitação já processada':'Resultado da contabilização'}}</h2><p role="status">{{result.created_count}} lançamento(s) {{result.duplicate?'registrado(s) na solicitação anterior; nenhuma nova gravação nesta repetição':'gerado(s)'}} · {{result.accounted_count}} nota(s) vinculada(s) · {{result.skipped.length}} ignorada(s).</p><p>{{result.notice}}</p><p v-for="j in result.journals" :key="j.id">Lançamento #{{j.number}} · {{date(j.date)}} · {{money(j.total_cents)}} <button class="button small" :disabled="!can('accounting.journals')||state.contextBusy" @click="showTrace('journal',j.id)">Notas do lançamento #{{j.number}}</button></p><ul v-if="result.skipped.length"><li v-for="s in result.skipped" :key="s.document_id">Nota #{{s.document_id}}: {{s.reason==='already_accounted'?'já contabilizada; vínculo preservado':'não apta; não houve contabilização'}}.</li></ul></section>
</section>
<section v-if="permitted" v-show="section==='settings'" id="fiscal-accounting-panel-settings" role="tabpanel" aria-labelledby="fiscal-accounting-tab-settings" class="panel sales-help"><section v-if="config&&direction==='outgoing'" class="sales-configuration" aria-label="Configuração contábil de saídas da empresa"><h2>Modo das saídas desta empresa</h2><div class="form-grid"><label>Geração de lançamentos<select v-model="mode" :disabled="locked||loading||!can('accounting.accounts','edit')"><option value="individual">Individual · um lançamento por nota</option><option value="daily">Diário · agrupar por data, classificação e contas</option></select></label><div class="actions"><span>{{modeDirty?'Escolha ainda não salva':`Modo salvo: ${config.mode==='daily'?'diário':'individual'}`}}</span><button type="button" class="button outline" :disabled="locked||loading||!modeDirty||!can('accounting.accounts','edit')" @click="saveMode">Salvar modo da empresa</button></div></div></section><p v-if="direction==='incoming'" class="report-note">Entradas geram um lançamento por nota. O modo salvo para saídas permanece preservado.</p><div class="sales-help-copy"><h2>Como funciona</h2><p>{{config?.notice||'A escolha de modo vale para novas notas desta integração; lançamentos existentes são preservados.'}}</p><p>Contas diretas são o caminho principal; modelos salvos são opcionais. O valor vem do total escriturado da nota, sem escolha automática de conta ou classificação.</p><h3>Seleção e competência</h3><p>Alternar estas subguias preserva seleção, contas e histórico. Trocar sentido, empresa, exercício ou filtros limpa a seleção. A competência da escrituração é independente da emissão. Competências fechadas exigem reabertura para contabilizar.</p><h3>Cobertura atual</h3><p>Importação automática e distribuição contábil por itens continuam pendentes. Os botões individuais mantêm o fluxo anterior. O Diário Consolidado apenas consulta lançamentos existentes.</p></div></section>
<BaseModal v-if="trace" title="Rastreabilidade contábil fiscal" wide @close="closeTrace"><p v-if="traceLoading" role="status">Consultando origens…</p><p v-if="traceError" class="message error" role="alert">{{traceError}}</p><template v-if="trace.data"><p v-if="trace.data.document">Nota {{trace.data.document.number}} · {{trace.data.document.partner_name}} · {{eligibilityLabel(trace.data.document)}}</p><section v-for="j in traceJournals" :key="j.id"><h3>Lançamento #{{j.number||j.id}}</h3><p v-if="j.deleted">Excluído fisicamente; referência histórica preservada.</p><template v-else><p>{{date(j.date)}} · {{money(j.total_cents)}} · {{j.history}}</p><table><thead><tr><th>Conta</th><th>Débito</th><th>Crédito</th></tr></thead><tbody><tr v-for="line in j.lines" :key="line.id"><td>{{line.access_code}} · {{line.account_name}}</td><td>{{money(line.debit_cents)}}</td><td>{{money(line.credit_cents)}}</td></tr></tbody></table></template></section><h3>Contribuições das notas</h3><p v-if="!traceSources.length">Sem contribuições registradas por esta integração. Os vínculos anteriores continuam preservados.</p><article v-for="(s,i) in traceSources" :key="`${s.document_id}-${s.journal_id}-${i}`" class="sales-source"><strong>Nota {{s.document_number}} · série {{s.document_series}} · {{money(s.total_cents)}}</strong><p>Escrituração {{date(s.posting_date)}} · emissão {{date(s.issue_date)}} · lançamento #{{s.journal_id}}</p><p v-if="s.entry_method==='direct'">Contas informadas diretamente nesta integração.</p><p v-if="s.model_snapshot">Modelo opcional: {{s.model_snapshot.code}} · {{s.model_snapshot.name}}</p><p v-for="(c,k) in s.classification.item_classifications" :key="k">{{classLabel(c)}}</p><details><summary>Identificação da origem</summary><p>Documento #{{s.document_id}} · versão fiscal {{s.document_version}}</p><p>Chave: {{s.document_key||'Não informada'}}</p><p class="wrap-anywhere">Hash de origem: {{s.source_hash||'Não informado'}}</p></details><button v-if="trace.kind==='journal'" class="button small" @click="showTrace('document',s.document_id)">Consultar nota {{s.document_number}}</button></article><template v-if="trace.data.reversals?.length"><h3>Compensações por nota</h3><p v-for="r in trace.data.reversals" :key="r.journal_id">Nota #{{r.document_id}} · lançamento de compensação #{{r.journal_id}} · {{money(r.total_cents)}}</p></template><p class="message subtle">As contribuições são históricas. Estornos e novas escriturações não apagam a origem anterior.</p></template><template #footer><button class="button" @click="closeTrace">Fechar rastreabilidade</button></template></BaseModal>
</div></template>
<style scoped>
.sales-generation,.sales-result,.sales-help{padding:20px}.sales-context{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));align-items:end;gap:16px;padding:14px 20px}.sales-context>label{min-width:0}.sales-mode{display:grid;justify-items:start;gap:4px}.sales-mode small{color:var(--muted)}.sales-selection-summary{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:12px 0}.sales-selection-summary>div:first-child{display:grid;gap:4px}.sales-selection-summary small{color:var(--muted)}.sales-accounting-panel{display:grid;gap:16px}.sales-help-copy{max-width:78ch}.sales-help-copy h2,.sales-help-copy h3{margin:18px 0 8px}.sales-post-actions{margin-top:14px;gap:8px;flex-wrap:wrap}.sales-configuration h2,.sales-generation h2,.sales-result h2{margin:0 0 12px}.sales-configuration .actions{align-self:end}.sales-selection{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;padding:10px 16px}.sales-generation{border:0}.sales-generation .button{align-self:end}.sales-optional-model{margin:16px 0}.sales-source{padding:14px 0;border-bottom:1px solid var(--border,#ddd)}.sales-source p{margin:8px 0}.sales-source details{margin:12px 0}.sales-source details p{overflow-wrap:anywhere}.sales-accounting-view .actions{flex-wrap:wrap}.sales-accounting-view select{max-width:100%}
@media(max-width:760px){.sales-context{grid-template-columns:1fr 1fr;gap:12px;padding:14px}.sales-mode{grid-column:1/-1}.sales-selection-summary{align-items:flex-start;flex-wrap:wrap}.sales-selection-summary .actions{width:100%}.sales-selection-summary .button{flex:1}.sales-generation,.sales-result,.sales-help{padding:16px}}@media(max-width:430px){.sales-context{grid-template-columns:1fr}.sales-mode{grid-column:auto}}
</style>
